    if params_klein is None:
      params_klein = {}; params_klein.update({'a':1,'b':1.6,'c':0.7,'n1':50,'n2':50,'device':device});

    # generate the arm configurations in R^4    
    X = GenDataArm1Klein.func_klein_R4_1(u_list,params_klein);
    self.params_klein = params_klein;

    self.noise_type = noise_type;
    self.params_noise = params_noise;

    if noise_type == 'none':
      self.samples_X_target = X;
    elif noise_type == 'Gaussian1':
      self.samples_X_target = X; 
      sigma = params_noise['sigma'];      
      eta = sigma*torch.randn(*X.shape,device=device);      
      X = X + eta;
      self.samples_X_noise = X;
    else:
      raise Exception("Not recognized, noise_type = " + noise_type);

    self.set_sample_mode(sample_mode);

  def set_sample_mode(self,sample_mode):

    if sample_mode == 'no_noise':
      self.samples_X = self.samples_X_target;
    elif sample_mode == 'with_noise':
      self.samples_X = self.samples_X_noise; 
    else:
      raise Exception("Not recognized, sample_mode = " + sample_mode);

    self.sample_mode = sample_mode;

  @staticmethod
  def func_klein_R4_1(u,params=None):
      a,b,c,device = tuple(map(params.get,['a','b','c','device']));

      if a is None:
        a = 3;
      if b is None:
        b = 4;  
      if c is None:
        c = 2;    
      if device is None:
        device = torch.device('cpu');

      num_dim_x = 4; num_samples_u = u.shape[0];
      x = torch.zeros(num_samples_u,num_dim_x,device=device);
      u1 = u[:,0]; u2 = u[:,1];
      x[:,0] = (a + b*torch.cos(u2))*torch.cos(u1);
      x[:,1] = (a + b*torch.cos(u2))*torch.sin(u1);
      x[:,2] = b*torch.sin(u2)*torch.cos(0.5*u1);
      x[:,3] = b*torch.sin(u2)*torch.sin(0.5*u1);

      return x;

  def __len__(self):    
    return self.samples_X.size()[0];

  def __getitem__(self,index):
    return self.samples_X[index];

  def to(self,device): 
    self.samples_X = self.samples_X.to(device);

    return self;

def get_manifold_sigma_info_klein1(x,params=None):
  # assumes x is 4D point on Klein bottle
  # chooses local coordinate chart 
  #   chart 1: sigma(u) = [x1,x2,x3,x4] (see below)
  #
  # \begin{eqnarray}
  #  x_1 & = & (a + b\cos(u_2))\cos(u_1) \\
  #  x_2 & = & (a + b\cos(u_2))\sin(u_1) \\
  #  x_3 & = & b\sin(u_2)\cos\left(\frac{u_1}{2}\right) \\
  #  x_4 & = & b\sin(u_2)\sin\left(\frac{u_1}{2}\right).
  # \end{eqnarray}
  #
  #device = params['device'];  
  params_klein = params['params_klein'];
  device = x.device;

  results = {}; num_samples = x.shape[0]; num_dim_x = x.shape[1]; num_dim_u = 2;

  # get chart and point information
  manifold_chart_I,manifold_chart_u,manifold_ptsX = tuple(map(params.get,['manifold_chart_I','manifold_chart_u',
                                                                          'manifold_ptsX']));

  I_x = params['I_x']; # assumes set by recent closest point algorithm call
  chart_I = manifold_chart_I[I_x]; u = manifold_chart_u[I_x,:];
  xx = manifold_ptsX[I_x,:]; # makes consistent

  # chart 0: # prototype for more general case (assumes one chart for now)
  II = torch.nonzero(chart_I == 0).squeeze(1);
  if II.shape[0] != num_samples:
    raise Exception("Assuming only one coordiate chart used for Klein Bottle currently.");      
  # We can use automatic differentiaion to get the derivatives needed and values
  # (we recompute the surface points to build local comp. call graph for taking derivatives)
  # this yields the 
  #   sigma_k with shape = [num_samples_u,num_dim_x]
  #   d_ui_sigma_k[II,i,k]  with shape = [num_samples_u,num_dim_u,num_dim_x]
  #   d_ui_uj_sigma_k with shape = [num_samples_u,num_dim_u,num_dim_u,num_dim_x]  
  with torch.enable_grad():
    sigma_k = torch.zeros(num_samples,num_dim_x,device=device);
    d_ui_sigma_k = torch.zeros(num_samples,num_dim_u,num_dim_x,device=device);
    d_ui_uj_sigma_k = torch.zeros(num_samples,num_dim_u,num_dim_u,num_dim_x,device=device);

    uu = u[II,:]; # get all u for the current chart
    uu = uu.detach().requires_grad_(True); # detach to make leaf variable of local comp. graph    
    sigma_k[II,:] = func_klein_R4_1(uu,params=params_klein); # sigma(u^*) = x (by assumption)    
    for k in range(0,num_dim_x):
      ss = torch.sum(sigma_k[II,k]);
      d_u_ss, = torch.autograd.grad(ss,uu,retain_graph=True,allow_unused=True,create_graph=True);
      for i in range(0,num_dim_u):
        d_ui_sigma_k[II,i,k] = d_u_ss[:,i];
        sss = torch.sum(d_u_ss[:,i]);
        d_u_u_ss, = torch.autograd.grad(sss,uu,retain_graph=True,allow_unused=False,create_graph=True); # @@@ check no side-effects
        for j in range(0,num_dim_u): # @@@ double-check no side-effect of calling twice
          d_ui_uj_sigma_k[II,i,j,k] = d_u_u_ss[:,j];

  results.update({'sigma_k':sigma_k,'d_ui_sigma_k':d_ui_sigma_k,'d_ui_uj_sigma_k':d_ui_uj_sigma_k});

  return results;

def func_klein_R4_1(u,params=None):
  a,b,c,device = tuple(map(params.get,['a','b','c','device']));

  if a is None:
    a = 3;
  if b is None:
    b = 4;  
  if c is None:
    c = 2;    
  if device is None:
    device = torch.device('cpu');

  num_dim_x = 4; num_samples_u = u.shape[0];
  x = torch.zeros(num_samples_u,num_dim_x,device=device);
  u1 = u[:,0]; u2 = u[:,1];
  x[:,0] = (a + b*torch.cos(u2))*torch.cos(u1);
  x[:,1] = (a + b*torch.cos(u2))*torch.sin(u1);
  x[:,2] = b*torch.sin(u2)*torch.cos(0.5*u1);
  x[:,3] = b*torch.sin(u2)*torch.sin(0.5*u1);

  return x;

def sample_klein_bottle_points_R4(params=None):

  a,b,n1,n2,device = tuple(map(params.get,['a','b','n1','n2','device']));

  if a is None:
    a = 3;
  if b is None:
    b = 4;  

  if n1 is None:
    n1 = 10; 
  if n2 is None:
    n2 = n1; 

  if device is None:
    device = torch.device('cpu');    

  num_dim_x = 4; num_samples_u = n1*n2;    
  pts_u1 = torch.linspace(0,2*np.pi,n1,device=device);
  pts_u2 = torch.linspace(0,2*np.pi,n2,device=device);    
  #u1,u2 = torch.meshgrid(pts_u1,pts_u2,indexing='ij'); # use in pytorch 1.11.0 or later
  u1,u2 = torch.meshgrid(pts_u1,pts_u2); # pytorch 1.11.0 or earlier
  u1 = u1.flatten(); u2 = u2.flatten();
  u = torch.stack((u1,u2),dim=1);

  u = u.requires_grad_(True); # needed for sigma info. later 

  params_k = {'a':a,'b':b,'device':device};
  x = func_klein_R4_1(u,params=params_k);

  return x, u;

def sample_klein_bottle_points_R3(params=None):  
  device = params['device']; 

  a,b,c,n1,n2 = tuple(map(params.get,['a','b','c','n1','n2']));

  if a is None:
    a = 6;
  if b is None:
    b = 16;  
  if c is None:
    c = 2;
  if n1 is None:
    n1 = 10; 
  if n2 is None:
    n2 = n1;     

  num_dim_x = 3;
  num_samples_u = n1*n2;

  # part 1
  # see parameterization in G. Franzoni, AMS Notices, 2012,
  # Dickson Bottle shape is:
  pts_u1 = torch.linspace(0,np.pi,n1,device=device);
  pts_u2 = torch.linspace(0,2*np.pi,n2,device=device);
  u1,u2 = torch.meshgrid(pts_u1,pts_u2,indexing='ij');
  u1 = u1.flatten(); u2 = u2.flatten();

  x = torch.zeros(num_samples_u,num_dim_x,device=device);  
  r_u1 = c*(1 - 0.5*torch.cos(u1));    
  x[:,0] = (a*(1 + torch.sin(u1)) + r_u1*torch.cos(u2))*torch.cos(u1); 
  x[:,1] = (b + r_u1*torch.cos(u2))*torch.sin(u1);
  x[:,2] = r_u1*torch.sin(u2);

  u = torch.stack((u1,u2),dim=1);
  xA = x; uA = u;

  # part 2
  pts_u1 = torch.linspace(np.pi,2*np.pi,n1,device=device);
  pts_u2 = torch.linspace(0,2*np.pi,n2,device=device);
  u1,u2 = torch.meshgrid(pts_u1,pts_u2,indexing='ij');
  u1 = u1.flatten(); u2 = u2.flatten();

  x = torch.zeros(num_samples_u,num_dim_x,device=device);  
  r_u1 = c*(1 - 0.5*torch.cos(u1));
  x[:,0] = a*(1 + torch.sin(u1))*torch.cos(u1) + r_u1*torch.cos(u2 + np.pi);
  x[:,1] = b*torch.sin(u1);
  x[:,2] = r_u1*torch.sin(u2);
  u = torch.stack((u1,u2),dim=1);
  xB = x; uB = u;

  x = torch.cat((xA,xB),dim=0);
  u = torch.cat((uA,uB),dim=0);

  return x,u;

def create_model_gd_vae_nn1(**params):
  params_theta, params_phi, device = tuple(map(params.get,['params_theta','params_phi', 'device']));

  # -- theta (decoder)
  layer_sizes, layer_biases, manifold_map, log_sigma_sq_0 = tuple(map(params_theta.get,
                                                                 ['layer_sizes', 'layer_biases', 
                                                                  'manifold_map','log_sigma_sq_0']));

  activation_type, params_activation = tuple(map(params_theta.get,['activation_type','params_activation']));

  if log_sigma_sq_0 is None:
    log_sigma_sq_0 = 0.1;

  if activation_type is None:
    activation_type = 'LeakyReLU';

  if params_activation is None:
    if activation_type == 'LeakyReLU':
      params_activation = {'negative_slope':1e-6}; # default 

  ss = layer_sizes; bb = layer_biases;
  seq_list = []; num_layers = len(layer_sizes) - 1;
  for k in range(0,num_layers):
    seq_list.append(torch.nn.Linear(ss[k],ss[k+1],bias=bb[k]));
    if k != (num_layers - 1):
      if activation_type == 'LeakyReLU':
        p = params_activation;
        seq_list.append(torch.nn.LeakyReLU(negative_slope=p['negative_slope']));
      else:
        raise Exception("Not recognized, activation_type = " + str(activation_type));

  if manifold_map is not None:
    seq_list.append(manifold_map);

  model_mu = torch.nn.Sequential(*seq_list).to(device);

  model_log_sigma_sq = torch.nn.Sequential(
    gd_vae.nn.AtzLearnableTensorLayer(tensor_size=(1,layer_sizes[-1]),device=device),    
  ).to(device);
  model_log_sigma_sq[0].data = log_sigma_sq_0;

  theta = {};
  theta.update({'model_mu':model_mu,'model_log_sigma_sq':model_log_sigma_sq});

  # -- phi (encoder)  
  layer_sizes, layer_biases, manifold_map, nu, beta, log_sigma_sq_0 = tuple(map(params_phi.get,
                                                                     ['layer_sizes', 'layer_biases', 
                                                                      'manifold_map','nu','beta','log_sigma_sq_0']));

  activation_type, params_activation = tuple(map(params_phi.get,['activation_type','params_activation']));

  if nu is None:
    nu = 0.5;

  if beta is None:
    beta = 1.0;

  if log_sigma_sq_0 is None:
    log_sigma_sq_0 = 0.1;

  if activation_type is None:
    activation_type = 'LeakyReLU';

  if params_activation is None:
    if activation_type == 'LeakyReLU':
      params_activation = {'negative_slope':1e-6}; # default 

  ss = layer_sizes; bb = layer_biases;
  seq_list = []; num_layers = len(layer_sizes) - 1;
  for k in range(0,num_layers):
    seq_list.append(torch.nn.Linear(ss[k],ss[k+1],bias=bb[k]));
    if k != num_layers - 1:
      if activation_type == 'LeakyReLU':
        p = params_activation;
        seq_list.append(torch.nn.LeakyReLU(negative_slope=p['negative_slope']));
      else:
        raise Exception("Not recognized, activation_type = " + str(activation_type));

  if manifold_map is not None:
    seq_list.append(manifold_map);

  model_mu = torch.nn.Sequential(*seq_list).to(device);    

  model_log_sigma_sq = torch.nn.Sequential(
    gd_vae.nn.AtzLearnableTensorLayer(tensor_size=(1,layer_sizes[-1]),device=device),
  ).to(device);
  model_log_sigma_sq[0].data = log_sigma_sq_0;

  nu = torch.Tensor([nu]).to(device);    
  beta = torch.Tensor([beta]).to(device);    

  phi = {}; 
  phi.update({'model_mu':model_mu,'model_log_sigma_sq':model_log_sigma_sq,'nu':nu,'beta':beta});

  model = {'theta':theta,'phi':phi};

  return model;

def create_model(**params_create):    
  type_model = params_create['type_model']; 

  if type_model == 'gd_vae_nn1':
    model = create_model_gd_vae_nn1(**params_create);
  else:
    raise Exception("Not recognized, type_model = " + type_model);  

  return model;

def get_data_of_model_select_arm1(theta,phi): 
  d = {};

  theta_model_mu, theta_model_log_sigma_sq = tuple(map(theta.get,['model_mu','model_log_sigma_sq']));
  phi_model_mu, phi_model_log_sigma_sq = tuple(map(phi.get,['model_mu','model_log_sigma_sq']));

  d['nu_phi'] = phi['nu'];

  mm = theta_model_mu;
  ll = list(mm[0].parameters());
  d['mu_theta_W1'] = ll[0].data;
  if len(ll) > 1:
    d['mu_theta_b1'] = ll[1].data;
  ll = list(mm[2].parameters());
  d['mu_theta_W2'] = ll[0].data;
  if len(ll) > 1:
    d['mu_theta_b2'] = ll[1].data;

  if theta_model_log_sigma_sq is not None:
    qq = theta_model_log_sigma_sq[0];
    if isinstance(qq,gd_vae.nn.AtzLearnableTensorLayer):
      d['log_sigma_sq_theta_tensor'] = qq.params['tensor'];

  mm = phi_model_mu;        
  ll = list(mm[0].parameters());
  d['mu_phi_W1'] = ll[0].data;
  if len(ll) > 1:
    d['mu_phi_b1'] = ll[1].data;
  ll = list(mm[2].parameters());
  d['mu_phi_W2'] = ll[0].data;
  if len(ll) > 1:    
    d['mu_phi_b2'] = ll[1].data;

  if phi_model_log_sigma_sq is not None:
    qq = phi_model_log_sigma_sq[0];
    if isinstance(qq,gd_vae.nn.AtzLearnableTensorLayer):
      d['log_sigma_sq_phi_tensor'] = qq.params['tensor'];

  return d;

def create_manifold_map_klein1(**extra_params):
  params_klein,device = tuple(map(extra_params.get,['params_klein','device']));

  # setup manifold description as point cloud
  x,u = pkg_geometry.sample_klein_bottle_points_R4(params_klein);
  num_samples = x.shape[0]; num_dim_x = x.shape[1]; num_dim_u = u.shape[1];
  manifold_chart_I = torch.zeros(num_samples,device=device);
  manifold_chart_u = torch.zeros(num_samples,num_dim_u,device=device);
  manifold_ptsX = torch.zeros(num_samples,num_dim_x,device=device);

  # chart 0: (only one chart for now)
  chart_I = 0; I = torch.arange(0,num_samples);
  manifold_chart_I[I] = chart_I;
  manifold_chart_u[I,:] = u[I,:];
  manifold_ptsX[I,:] = x[I,:];

  # setup closest point
  params_map = {};
  params_map.update({'manifold_chart_I':manifold_chart_I,
                     'manifold_chart_u':manifold_chart_u,
                     'manifold_ptsX':manifold_ptsX});

  params_map.update({'find_nearest_manifold_pt':gd_vae.geo_map.PointCloudMapFunc.find_nearest_manifold_pt_kdtree});
  params_map.update({'find_nearest_manifold_pt_params':{'manifold_ptsX':manifold_ptsX}});

  params_map.update({'get_manifold_sigma_info':pkg_geometry.get_manifold_sigma_info_klein1});
  params_map.update({'get_manifold_sigma_info_params':{'manifold_chart_I':manifold_chart_I,
                                                       'manifold_chart_u':manifold_chart_u,
                                                       'manifold_ptsX':manifold_ptsX,
                                                       'params_klein':params_klein,
                                                       'device':device}});

  manifold_map = gd_vae.geo_map.ManifoldPointCloudLayer(params_map); # can be used as part of PyTorch pipeline with backprop

  return manifold_map;

